    /// and other gifts can be bought only if getOption("can_buy_on_chain_gifts") is true. The type of the returned transaction depends on the type of the sale. The gift will be received by the new owner
    /// after the transaction is executed on the TON blockchain. If the gift is bought for the current user, then it will be received by the TON wallet of the current user,
    /// and will be shown on the user's profile page if it is still in the wallet
    /// </summary>
    public class GetGiftOnChainPurchaseTransaction : Function<GiftOnChainSaleTransaction>
    {
        /// <summary>
        /// Data type for serialization
        /// </summary>
        [JsonProperty("@type")]
        public override string DataType { get; set; } = "getGiftOnChainPurchaseTransaction";

        /// <summary>
        /// Extra data attached to the function.
        /// </summary>
        /// <remarks>
        /// TdSharp internally uses this to find responses corresponding to each request initiated by the user.
        /// </remarks>
        [JsonProperty("@extra")]
        public override string ExtraData { get; set; }

        /// <summary>
        /// Name of the upgraded gift
        /// </summary>
        [JsonConverter(typeof(Converter))]
        [JsonProperty("gift_name")]
        public string GiftName { get; set; }

        /// <summary>
        /// Identifier of the user or the channel chat that will receive the gift; must be the current user if giftResaleParameters.is_fixed_on_chain is false
