    /// after the transaction is executed on the TON blockchain. If the gift is bought for the current user, then it will be received by the TON wallet of the current user,
    /// and will be shown on the user's profile page if it is still in the wallet
    /// </summary>
    public static Task<GiftOnChainSaleTransaction> GetGiftOnChainPurchaseTransactionAsync(
        this IClient client, string giftName = default, MessageSender ownerId = default, long gramAmount = default, FormattedText text = default, bool isPrivate = default)
    {
        return client.ExecuteAsync(new GetGiftOnChainPurchaseTransaction
